 cmd=req['command'];assert cmd[1]=='exec' and cmd[cmd.index('-i')+1]==req['cwd']+'/chart.png' and cmd[cmd.index('-o')+1]==req['cwd']+'/final.txt';sources.append({'case':c['case'],'thread_id':r['thread_id'],'source_sha256':sha(source)})
